SELECT
    [P1].[SegmentName] AS [c0],
    COUNT_BIG(*) AS [c1]
FROM [gl].[Documents] AS [T]
INNER JOIN [gl].[Segments] AS [P1] ON [P1].[SegmentId] = [T].[SegmentId]
GROUP BY [P1].[SegmentName]
HAVING (((SELECT DATEADD(DAY, 365 * (((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) / 13) - 1) + ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) / 13) / 4 + 30 * ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) % 13) + LEAST(((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) % 30, (29 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) % 13) / 12 * (25 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST([N2].[v] AS int)) / 13) % 4 / 3))) - (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922), [N1].[v]) FROM (VALUES (MAX([T].[PostingDate]))) AS [N1] ([v]) CROSS APPLY (VALUES (COUNT_BIG([T].[DocumentId]))) AS [N2] ([v])) > MIN([T].[PostingDate])) AND (CASE WHEN ((SELECT (SELECT DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V2].[v])), [V2].[v]) FROM [core].[CalendarMonths] AS [M2] CROSS APPLY (VALUES (COUNT_BIG([T].[DocumentId]))) AS [V1] ([v]) WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[Year] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST([V1].[v] AS int)) / 12) AND [M2].[Month] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST([V1].[v] AS int)) % 12 + 1)) FROM (VALUES (MAX([T].[PostingDate]))) AS [V2] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V2].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V2].[v] < [M].[EndDate]) > MIN([T].[PostingDate])) THEN 1 ELSE 0 END = 1) AND (CASE WHEN ((SELECT (SELECT DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V1].[v])), [V1].[v]) FROM [core].[CalendarMonths] AS [M2] WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[Year] = ([M].[Year] + CAST(SUM(CASE WHEN [T].[DocumentId] IS NOT NULL THEN @qx0_p1 END) AS int)) AND [M2].[Month] = [M].[Month]) FROM (VALUES (MAX([T].[PostingDate]))) AS [V1] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V1].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V1].[v] < [M].[EndDate]) > MIN([T].[PostingDate])) THEN 1 ELSE 0 END = 1))
;

-- parameters
--   @qx0_p0 : QxString QxVarChar(8000) Literal = 'uq'
--   @qx0_p1 : QxNumeric QxDecimal(1, 0) Literal = 1
-- columns
--   0 : QxString NotNull key path=Centre.Name Centre.Name
--   1 : QxNumeric NotNull count()
